def handler(event, ctx):
    r = event["http"]["gatewayResponse"]
    if not r.get("isStreamingResponse"):
        return {"interceptorOutputVersion": "1.0",
                "http": {}}
    out = []
    for e in r["events"]:
        d = e["data"]
        # redact: check joined neighbours
        out.append({"data": d})
    return {"interceptorOutputVersion": "1.0",
            "http": {"transformedGatewayResponse":
                     {"events": out}}}
